import './cloud-sync.js';
import{FRACTION_TRACKS,FRACTION_CHAIN,FRACTION_DIAGNOSTIC,recommendFractionTrack,sameFraction,fractionValue,createBlankFractionLearner}from'./fraction-data.js';

const $=s=>document.querySelector(s),storageKey='mathlab-fraction-v1',memory={};
function blankStore(){return{a:createBlankFractionLearner(),b:createBlankFractionLearner(),learner:'a'}}
function readStore(){try{return JSON.parse(localStorage.getItem(storageKey))||blankStore()}catch{return memory.data||blankStore()}}
let store=readStore(),learner=store.learner||'a',state=store[learner]||createBlankFractionLearner(),hintLevel=0,attempts=0,sessionMissionId=null;
function ensureState(){state={...createBlankFractionLearner(),...state,diagnostic:{...createBlankFractionLearner().diagnostic,...state.diagnostic},missions:{...state.missions},sessions:{...state.sessions},evidence:{...createBlankFractionLearner().evidence,...state.evidence},family:{...createBlankFractionLearner().family,...state.family}}}
function save(){state.updatedAt=new Date().toISOString();store={...readStore(),[learner]:state,learner};memory.data=store;try{localStorage.setItem(storageKey,JSON.stringify(store));$('#saveStatus').textContent='Saved offline · cloud sync follows parent sign-in'}catch{$('#saveStatus').textContent='Progress lasts until this page closes.'}}
function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function feedback(text,type=''){const el=$('#feedback');el.textContent=text;el.className='feedback '+type}
function track(){return FRACTION_TRACKS[state.track||'explorer']}
function done(i){return Boolean(state.missions[FRACTION_CHAIN.missions[i].id]?.complete)}
function unlocked(i){return i===0||done(i-1)}
function mark(dim,independent=true){if(independent)state.evidence[dim]='independent';else if(state.evidence[dim]==='unknown')state.evidence[dim]='learning'}
function loadSession(id){sessionMissionId=id;const saved=state.sessions[id]||{attempts:0,hints:0};attempts=Number(saved.attempts)||0;hintLevel=Number(saved.hints)||0}
function saveSession(){if(!sessionMissionId)return;state.sessions[sessionMissionId]={attempts,hints:hintLevel};save()}
function complete(i,dims=[],pending=false,preview=false){const m=FRACTION_CHAIN.missions[i];state.missions[m.id]={complete:!preview,preview,attempts,hints:hintLevel,completedAt:new Date().toISOString(),track:state.track};dims.forEach(d=>mark(d,attempts<=1&&hintLevel===0&&!preview));if(pending){state.retestDue=Date.now()+20*60*60*1000;state.evidence.explanation=state.evidence.explanation==='unknown'?'learning':state.evidence.explanation}if(!preview&&i<4)state.activeMission=i+1;delete state.sessions[m.id];attempts=0;hintLevel=0;sessionMissionId=null;save();setTimeout(render,450)}
function tryOnce(){attempts++;saveSession()}
function hint(text){return hintLevel?`<div class="hint-box">${esc(text)}</div>`:''}
function controls(){return `<div class="answer-row"><button class="secondary" data-action="hint">Give me one hint</button></div>`}
function bar(n,d,label=''){return `<div class="fraction-model"><div class="fraction-bar-model" style="grid-template-columns:repeat(${d},1fr)">${Array.from({length:d},(_,i)=>`<span class="${i<n?'filled':''}"></span>`).join('')}</div><strong>${label||`${n}/${d}`}</strong></div>`}
function numberLine(d,target){return `<div class="fraction-line" style="grid-template-columns:repeat(${d+1},1fr)">${Array.from({length:d+1},(_,i)=>`<button data-point="${i}" aria-label="${i} out of ${d}"><i></i><span>${i===0?'0':i===d?'1':`${i}/${d}`}</span></button>`).join('')}</div><p class="model-caption">Every step is the same distance because the whole from 0 to 1 is split equally.</p>`}

function renderDiagnostic(){const d=state.diagnostic;if(d.index>=FRACTION_DIAGNOSTIC.length){state.track=state.track||recommendFractionTrack(d.score);const t=track();$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">STARTING DEPTH FOUND</p><h3>${t.label}</h3><p>${t.description}</p><p class="microcopy">This chooses useful numbers. It is not a grade label.</p><button class="primary" data-action="start">Build equal shares →</button></div>`;return}const q=FRACTION_DIAGNOSTIC[d.index];$('#activity').innerHTML=`<div class="diagnostic-progress"><span style="width:${d.index/FRACTION_DIAGNOSTIC.length*100}%"></span></div><p class="eyebrow">QUESTION ${d.index+1} OF ${FRACTION_DIAGNOSTIC.length}</p><h3>${esc(q.prompt)}</h3><div class="answer-grid">${q.choices.map((x,i)=>`<button class="choice" data-diagnostic="${i}">${esc(x)}</button>`).join('')}</div><p class="microcopy">No timer. A grown-up may read the words aloud.</p>`;document.querySelectorAll('[data-diagnostic]').forEach(b=>b.onclick=()=>{const correct=Number(b.dataset.diagnostic)===q.answer;d.answers.push({id:q.id,correct});if(correct)d.score++;d.index++;feedback(correct?'That relationship is clear.':q.why,correct?'good':'try');save();setTimeout(()=>{feedback('');render()},500)})}
function renderShares(){const t=track(),{parts,target}=t.share;$('#activity').innerHTML=`<p class="eyebrow">BUILD ONE FRACTION</p><h3>Shade exactly ${target}/${parts} of one whole.</h3><p class="prompt">Tap equal parts. Tap again to remove a part.</p><div id="shareBuilder" class="share-builder" style="grid-template-columns:repeat(${parts},1fr)">${Array.from({length:parts},(_,i)=>`<button data-share="${i}" aria-label="Part ${i+1}"></button>`).join('')}</div><p id="shareCount" class="equation">0/${parts}</p><button class="primary" data-action="checkShares">Check my fraction</button>${controls()}${hint(`The bottom number says there are ${parts} equal parts in the whole. The top number says to shade ${target} of them.`)}`;document.querySelectorAll('[data-share]').forEach(b=>b.onclick=()=>{b.classList.toggle('filled');$('#shareCount').textContent=`${document.querySelectorAll('[data-share].filled').length}/${parts}`})}
function checkShares(){tryOnce();const t=track(),count=document.querySelectorAll('[data-share].filled').length;if(count===t.share.target){feedback(`Yes. The whole has ${t.share.parts} equal parts, and ${count} are selected.`,'good');mark('whole');complete(1,['representation'])}else feedback(`You selected ${count} parts. The numerator asks for ${t.share.target}.`,'try')}
function renderLine(){const t=track(),{parts,target}=t.line;$('#activity').innerHTML=`<p class="eyebrow">SHAPE TO DISTANCE</p><h3>Where is ${target}/${parts} on the number line?</h3>${bar(target,parts)}${numberLine(parts,target)}${controls()}${hint(`Start at 0. Count ${target} equal steps when the distance to 1 is split into ${parts} parts.`)}`;document.querySelectorAll('[data-point]').forEach(b=>b.onclick=()=>{tryOnce();if(Number(b.dataset.point)===target){b.classList.add('correct-point');feedback(`${target}/${parts} means ${target} equal steps of size 1/${parts} from zero.`,'good');complete(2,['representation'])}else feedback('Count equal spaces from zero. The tick marks are boundaries; the spaces are the fractional steps.','try')})}
function renderEquivalent(){const t=track(),[an,ad]=t.equivalent.a,[bn,bd]=t.equivalent.b;$('#activity').innerHTML=`<p class="eyebrow">ALIGN THE WHOLES</p><h3>Do ${an}/${ad} and ${bn}/${bd} cover the same amount?</h3><div class="aligned-bars">${bar(an,ad,`${an}/${ad}`)}${bar(bn,bd,`${bn}/${bd}`)}</div><p class="prompt">Choose the evidence that proves the relationship.</p><div class="answer-grid"><button class="choice" data-proof="same">The bars end at the same place, and ${an} × ${bd/ad} = ${bn} while ${ad} × ${bd/ad} = ${bd}.</button><button class="choice" data-proof="different">The denominators are different, so the amounts must be different.</button><button class="choice" data-proof="guess">Both numerators are smaller than the denominators.</button></div>${controls()}${hint('Compare the length covered, not just the numbers. Multiplying numerator and denominator by the same number renames the parts without changing the amount.')}`;document.querySelectorAll('[data-proof]').forEach(b=>b.onclick=()=>{tryOnce();if(b.dataset.proof==='same'&&sameFraction(an,ad,bn,bd)){feedback('Exactly. More, smaller parts can cover the same length.','good');complete(3,['equivalence','explanation'],true)}else feedback('A proof must show that both fractions cover the same part of equal-sized wholes.','try')})}
function renderFresh(){const due=state.retestDue||Date.now()+20*60*60*1000,ready=Date.now()>=due;if(!ready&&!state.previewFresh){const hours=Math.max(1,Math.ceil((due-Date.now())/3600000));$('#activity').innerHTML=`<div class="lock-card"><p class="eyebrow">FRESH CHECK</p><strong>Return after the picture has faded from memory.</strong><p>About ${hours} hours remain. Waiting helps us see whether the idea is stable.</p><button class="secondary" data-action="preview">Preview for family review</button><p class="microcopy">The preview uses different numbers and will not count as delayed evidence.</p></div>`;return}const t=track(),pair=ready?t.fresh.challenge:t.fresh.preview,[n,d]=pair;const simpleD=d/(n===0?1:gcd(n,d)),simpleN=n/(n===0?1:gcd(n,d));$('#activity').innerHTML=`<p class="eyebrow">${ready?'DELAYED CHECK · NEW NUMBERS':'FAMILY PREVIEW · NOT DELAYED EVIDENCE'}</p><h3>A recipe uses ${n}/${d} cup of oats.</h3>${bar(n,d)}<p class="prompt">Which fraction names the same amount in simplest form?</p><div class="answer-grid"><button class="choice" data-fresh="correct">${simpleN}/${simpleD}</button><button class="choice" data-fresh="wrong">${Math.min(d,n+1)}/${d}</button><button class="choice" data-fresh="wrong">${n}/${Math.max(1,d-1)}</button></div><div id="freshWhy" hidden><p class="prompt">Why?</p><div class="answer-grid"><button class="choice" data-why="correct">Both numerator and denominator were divided by the same factor, so the amount stayed the same.</button><button class="choice" data-why="wrong">The numbers became smaller, so the fraction became smaller.</button></div></div>${controls()}${hint('Look for a number that divides both the numerator and denominator. The picture must keep the same endpoint.')}`;let accepted=false;document.querySelectorAll('[data-fresh]').forEach(b=>b.onclick=()=>{tryOnce();if(b.dataset.fresh==='correct'){accepted=true;$('#freshWhy').hidden=false;feedback('The amount matches. Now explain why.','good')}else feedback('Check which choice reaches the same endpoint on an equal-sized whole.','try')});document.querySelectorAll('[data-why]').forEach(b=>b.onclick=()=>{if(!accepted)return;tryOnce();if(b.dataset.why==='correct'){feedback(ready?'You used and explained the relationship with new numbers.':'Preview complete. Return later for fresh evidence.','good');complete(4,['equivalence','explanation'],false,!ready)}else feedback('Changing both numbers by the same factor renames the parts; it does not change the amount.','try')})}
function gcd(a,b){while(b)[a,b]=[b,a%b];return Math.abs(a)}
function renderComplete(i){const m=FRACTION_CHAIN.missions[i];$('#activity').innerHTML=`<div class="complete-card"><div class="big-check">✓</div><p class="eyebrow">MISSION COMPLETE</p><h3>${esc(m.title)}</h3><p>Your work is saved for ${learner==='a'?'Ella':'Mila'}.</p>${i<4?'<button class="primary" data-action="next">Continue →</button>':'<a class="primary" href="./" style="text-decoration:none">Return home</a>'}</div>`}
function renderMission(){const i=state.activeMission,m=FRACTION_CHAIN.missions[i];if(sessionMissionId!==m.id)loadSession(m.id);$('#missionEyebrow').textContent=`MISSION ${m.number} · ${m.kind.replace('-',' ').toUpperCase()}`;$('#missionTitle').textContent=m.title;$('#missionObjective').textContent=m.objective;$('#missionTime').textContent=`ABOUT ${m.minutes} MIN`;feedback('');if(done(i)){renderComplete(i);return}if(i===0)renderDiagnostic();else if(i===1)renderShares();else if(i===2)renderLine();else if(i===3)renderEquivalent();else renderFresh()}
function renderNav(){$('#missionNav').innerHTML=FRACTION_CHAIN.missions.map((m,i)=>`<button class="mission-button ${i===state.activeMission?'active':''} ${unlocked(i)?'':'locked'}" data-mission="${i}" ${unlocked(i)?'':'disabled'}><span class="mission-number">${m.number}</span><span class="mission-label">${esc(m.title)}</span><span class="mission-state">${done(i)?'✓':unlocked(i)?'›':'◌'}</span></button>`).join('');document.querySelectorAll('[data-mission]').forEach(b=>b.onclick=()=>{state.activeMission=Number(b.dataset.mission);attempts=0;hintLevel=0;save();render()})}
function renderTrack(){const t=track();$('#trackCard').innerHTML=`<strong>Current depth: ${t.label}</strong><span>${t.description}</span><select id="trackSelect" aria-label="Learning depth">${Object.values(FRACTION_TRACKS).map(x=>`<option value="${x.id}" ${x.id===t.id?'selected':''}>${x.label}</option>`).join('')}</select><small>Changing depth restarts this review path so evidence is not mixed.</small>`;$('#trackSelect').onchange=e=>{state={...createBlankFractionLearner(),track:e.target.value,family:state.family};sessionMissionId=null;save();render()}}
function renderEvidence(){const labels={whole:'Whole & equal parts',representation:'Models & number line',equivalence:'Equivalent fractions',explanation:'Explain & transfer'};$('#evidenceGrid').innerHTML=Object.entries(labels).map(([k,v])=>`<div class="evidence-item"><header><span>${v}</span><span>${state.evidence[k]==='independent'?'Independent':state.evidence[k]==='learning'?'Learning':'Not checked'}</span></header></div>`).join('')}
function renderFamily(){$('#helpNote').value=state.family.help;$('#explainNote').value=state.family.explain;$('#continueNote').value=state.family.continue}
function render(){ensureState();$('#learnerSelect').value=learner;renderTrack();renderNav();renderEvidence();renderFamily();renderMission()}

document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const a=b.dataset.action;if(a==='start'){state.missions['fraction-start']={complete:true,score:state.diagnostic.score,completedAt:new Date().toISOString()};state.activeMission=1;sessionMissionId=null;save();render()}else if(a==='next'){state.activeMission=Math.min(4,state.activeMission+1);sessionMissionId=null;save();render()}else if(a==='hint'){hintLevel++;saveSession();renderMission()}else if(a==='checkShares')checkShares();else if(a==='preview'){state.previewFresh=true;save();render()}});
$('#learnerSelect').onchange=e=>{learner=e.target.value;state=readStore()[learner]||createBlankFractionLearner();sessionMissionId=null;ensureState();save();render()};
for(const[id,key]of[['helpNote','help'],['explainNote','explain'],['continueNote','continue']])$('#'+id).addEventListener('input',e=>{state.family[key]=e.target.value;save()});
$('#resetPath').onclick=()=>{if(confirm(`Reset the fraction review path for ${learner==='a'?'Ella':'Mila'}?`)){state=createBlankFractionLearner();sessionMissionId=null;save();render()}};
if('serviceWorker'in navigator)window.addEventListener('load',()=>navigator.serviceWorker.register('sw.js'));
ensureState();render();
